const $=id=>document.getElementById(id),content=$('content');let orders=[],checkouts=[],view='overview';
const statusText={prepared:'Klar til PF',gateway_accepted:'PF har modtaget',awaiting_proof:'Afventer korrektur',proof_received:'Til gennemgang',approval_pending_pf:'Afventer PF-kvittering',revision_requested:'Ændring ønsket',approval_recorded:'PF-godkendelse registreret',processing:'Under behandling',shipped:'Afsendt',needs_attention:'Kræver opmærksomhed',needs_reconciliation:'Kræver afstemning',cancelled:'Annulleret'};
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(className)node.className=className;return node;}
function link(text,href,light=false){const a=el('a',text,'action'+(light?' light':''));a.href=href;return a;}
function panel(title){const item=el('section',undefined,'panel');item.append(el('h2',title));return item;}
function row(order){const item=el('div',undefined,'row'),info=el('div');info.append(el('strong',order.purchaseOrderNumber),el('small',new Date(order.updatedAt).toLocaleString('da-DK')));item.append(info,el('span',statusText[order.status]||order.status,'status'+(['proof_received','approval_pending_pf','needs_attention'].includes(order.status)?' pending':'')));return item;}
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method==='POST'?{'X-Smerch-Admin':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!response.ok){let data;try{data=await response.json();}catch{}throw Error(data?.error||`HTTP ${response.status}`);}return response;}
function showLogin(){document.getElementById('login-view').hidden=false;document.getElementById('admin-app').hidden=true;}
function showApp(){document.getElementById('login-view').hidden=true;document.getElementById('admin-app').hidden=false;}
function render(){const title={overview:'Overblik',proofs:'Korrekturer',orders:'Ordrer',integration:'PF-integration'}[view];$('page-title').textContent=title;document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));content.replaceChildren();const pending=orders.filter(order=>order.status==='proof_received'),pfWaiting=orders.filter(order=>order.status==='approval_pending_pf');$('proof-count').textContent=pending.length||'';
 if(view==='overview'){content.append(el('p','Her samles de ordrer og korrekturer, der kræver jeres næste handling.','intro'));const metrics=el('div',undefined,'metrics');for(const [number,label] of [[pending.length,'Korrekturer til gennemgang'],[pfWaiting.length,'Afventer PF-kvittering'],[orders.length,'Ordrer i systemet']]){const card=el('div',undefined,'metric');card.append(el('strong',number),el('span',label));metrics.append(card);}content.append(metrics);const grid=el('div',undefined,'grid'),proofPanel=panel('Kræver jeres gennemgang'),nextPanel=panel('Næste skridt');for(const order of pending.slice(0,5))proofPanel.append(row(order));if(!pending.length)proofPanel.append(el('p','Ingen nye korrekturer lige nu.','muted'));proofPanel.append(link('Åbn korrekturindbakken →','/admin/pf-orders'));nextPanel.append(el('p','Godkendte korrekturer skal sendes gennem PF’s aftalte kanal. Først når PF har kvitteret, kan godkendelsen registreres som modtaget.'));nextPanel.append(link('Se PF-integration', '/admin#integration',true));grid.append(proofPanel,nextPanel);content.append(grid);return;}
 if(view==='proofs'){content.append(el('p','Alle modtagne korrekturer er versionsstyret. En ny version kræver en ny gennemgang.','intro'));const box=panel('Korrekturindbakke');for(const order of orders.filter(order=>['proof_received','approval_pending_pf','revision_requested'].includes(order.status)))box.append(row(order));if(box.children.length===1)box.append(el('p','Ingen korrekturer endnu.','muted'));box.append(link('Åbn korrekturer →','/admin/pf-orders'));content.append(box);return;}
 if(view==='orders'){content.append(el('p','Reservationer, hævninger og ordrestatus hos PF. Produktion kræver både hævet betaling og PF’s kvittering.','intro'));const paid=panel('Betalinger fra webshoppen');for(const order of checkouts){const item=el('div',undefined,'order-card'),info=el('div'),details=order.lines.map(line=>`${line.quantity} × ${line.productId} (${line.sku})${line.decorations.length?` · ${line.decorations.map(d=>`${d.method}, ${d.position}${d.text?`, tekst: ${d.text}`:''}`).join('; ')}`:''}`).join(', ');info.append(el('strong',`${order.id} · ${(order.totalIncVat/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'})}`),el('small',`${order.shipping.name} · ${order.shipping.email} · ${order.shipping.phone} · ${order.shipping.street}, ${order.shipping.postalCode} ${order.shipping.city} · ${details} · ${new Date(order.createdAt).toLocaleString('da-DK')}`));if(order.quickpayPaymentId)info.append(el('small',`Quickpay-betaling ${order.quickpayPaymentId}`));if(order.authorizationExpiresAt)info.append(el('small',`Reservation udløber ${new Date(order.authorizationExpiresAt).toLocaleString('da-DK')}`));if(order.pfHandoff?.status==='blocked')info.append(el('small',`PF-afsendelse kræver handling: ${order.pfHandoff.reason}`,'status pending'));if(['authorized','capture_reconciliation','paid'].includes(order.status))for(const artwork of order.artworks)info.append(link(`Hent ${artwork.name} ↓`,`/api/admin/checkouts/${order.id}/artwork/${artwork.id}`,true));if(order.status==='authorized'&&order.pfHandoff?.status==='blocked'){order.lines.forEach((line,lineIndex)=>line.decorations.forEach((deco,decorationIndex)=>{const key=`${lineIndex}:${decorationIndex}`,wrap=el('div',undefined,'colour-override');wrap.append(el('small',`${line.productId} · ${deco.position} · ${deco.colors} PF-farvekode(r)`));const field=el('input');field.placeholder='Fx 186 C, Black C';field.value=(order.pfColourOverrides?.[key]||[]).join(', ');field.setAttribute('aria-label',`PF-farver for ${line.productId} ${deco.position}`);const save=el('button','Gem PF-farver','action light');save.onclick=async()=>{try{await api(`/api/admin/checkouts/${order.id}/colours`,'POST',{lineIndex,decorationIndex,codes:field.value.split(',').map(value=>value.trim()).filter(Boolean)});await load();}catch(error){$('feedback').textContent=error.message;}};wrap.append(field,save);info.append(wrap);}));}if(order.status==='authorized'&&order.pfHandoff?.status==='blocked'){const retry=el('button','Prøv PF-afsendelse igen','action light');retry.onclick=async()=>{try{await api(`/api/admin/checkouts/${order.id}/retry-handoff`,'POST');await load();}catch(error){$('feedback').textContent=error.message;}};info.append(retry);}if(['authorized','authorization_expired','expired','payment_failed','awaiting_payment'].includes(order.status)){const cancel=el('button','Annullér ordre','action light');cancel.onclick=async()=>{try{if(!confirm('Annullér kundeordren og frigiv en eventuel reservation? PF skal kontaktes separat, hvis ordren er afsendt.'))return;await api(`/api/admin/checkouts/${order.id}/cancel`,'POST');await load();}catch(error){$('feedback').textContent=error.message;}};info.append(cancel);}if(order.status==='cancelled'&&order.pfOrderIds.length)info.append(el('small','PF skal have en separat annullering og kvittere for den.','status pending'));item.append(info,el('span',order.status==='paid'?'Hævet':order.status==='authorized'?'Reserveret':order.status==='capture_reconciliation'?'Afstem hævning':order.status==='awaiting_payment'?'Afventer reservation':order.status==='authorization_expired'?'Reservation udløbet':order.status==='expired'?'Betalingslink udløbet':'Kræver handling','status'+(['authorized','capture_reconciliation'].includes(order.status)?' pending':'')));paid.append(item);}if(!checkouts.length)paid.append(el('p','Ingen webshopbetalinger endnu.','muted'));content.append(paid);const list=panel('PF-ordrer');for(const order of orders){const card=el('div',undefined,'order-card'),info=el('div');info.append(el('strong',order.purchaseOrderNumber),el('small',`${order.lines?.reduce((n,line)=>n+line.quantity,0)||0} stk. · ${order.lines?.map(line=>line.productId).join(', ')||'Produkt ukendt'} · ${new Date(order.updatedAt).toLocaleString('da-DK')}`));card.append(info,el('span',statusText[order.status]||order.status,'status'),link('Se ordre →','/admin/pf-orders',true));list.append(card);}if(list.children.length===1)list.append(el('p','Der er endnu ingen PF-ordrer.','muted'));content.append(list);return;}
 const box=panel('Status på PF-forbindelsen');box.append(el('p','PF’s ordre-Gateway, statusbeskeder og korrekturindbakke er adskilte trin. Automatisk korrekturgodkendelse kræver, at PF oplyser og aktiverer den konkrete kanal.'));api('/api/pf-orders/status').then(response=>response.json()).then(result=>{const state=el('p',result.ready?`Gateway: klar (${result.mode})`:`Gateway: ikke klar (${result.mode||'off'})`,'status '+(result.ready?'ready':'pending'));box.append(state);if(result.missing?.length){const list=el('ul');for(const name of result.missing)list.append(el('li',name));box.append(el('p','Mangler fra PF eller serveropsætning:'),list);}if(result.nextStep)box.append(el('p',result.nextStep,'muted'));if(result.ready&&result.mode==='test')box.append(link('Opret Gateway-testordre →','/admin/pf-orders'));}).catch(()=>box.append(el('p','Gateway-status kunne ikke hentes.','status pending')));box.append(el('p','Interne godkendelser frigiver ikke produktionen, før PF faktisk har kvitteret.','muted'));content.append(box);
}
async function load(){try{[orders,checkouts]=await Promise.all([api('/api/pf-orders').then(r=>r.json()),api('/api/admin/checkouts').then(r=>r.json())]);showApp();render();$('feedback').textContent='';}catch(error){$('feedback').textContent=error.message;if(error.message.includes('Administratoradgang'))showLogin();}}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;history.replaceState(null,'',view==='overview'?'/admin':`/admin#${view}`);document.getElementById('admin-app').classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');render();}));
document.getElementById('admin-login').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form);try{await api('/api/admin/login','POST',{username:String(data.get('username')||'').trim(),password:String(data.get('password')||'')});form.elements.password.value='';await load();}catch(error){form.elements.password.value='';$('login-error').textContent=error.message;}});
$('logout').onclick=async()=>{try{await api('/api/admin/logout','POST');}finally{location.assign('/');}};$('refresh').onclick=load;$('menu-toggle').onclick=()=>{const active=document.getElementById('admin-app').classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',String(active));};
view=['proofs','orders','integration'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';api('/api/admin/session').then(response=>response.json()).then(state=>state.authenticated?load():showLogin()).catch(showLogin);
